/// <summary>
/// The <c>METCustFreeInvoiceForm_CustInvoiceTable_Extension</c> class manages enabled or disable the bulkworkflow button.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
[ExtensionOf(formDataSourceStr(CustFreeInvoice, CustInvoiceLine))]
public final class METCustFreeInvoiceForm_CustInvoiceLine_Extension
{
}

Method.Source:
/// <summary>
/// CustInvoiceLine formDatasource written method.
/// </summary>
public void written()
{
    next written();

    if (METBulkWFFreeTextInvoiceHelper::checkUserIdIsPartofExclusionlist())
    {
        FormRun             formRun =  this.formRun();
        FormDataSource      custInvoiceTableDataSource = formRun.dataSource(FormDatasourceStr(CustFreeInvoice, CustInvoiceTable));
        CustInvoiceTable    custInvoiceTable = custInvoiceTableDataSource.cursor() as CustInvoiceTable;

        if (custInvoiceTable)
        {
            custInvoiceTable.WorkflowApprovalStatus = CustFreeInvoiceWFApprovalStatus::Approved;
            custInvoiceTable.update();
        }

        formRun.design().controlName(formControlStr(Custfreeinvoice, ButtonCustPostInvoiceJob)).enabled(custInvoiceTable.canPost());
    }
}
